class Solution {
    public void setZeroes(int[][] A) {
        int row = A.length;
        int col = A[0].length;
        boolean firstRowHasZero = false;
        boolean firstColHasZero = false;

        // Check if the first row has any zeros
        for (int j = 0; j < col; j++) {
            if (A[0][j] == 0) {
                firstRowHasZero = true;
                break;
            }
        }

        // Check if the first column has any zeros
        for (int i = 0; i < row; i++) {
            if (A[i][0] == 0) {
                firstColHasZero = true;
                break;
            }
        }

        // Use the first row and column to mark zeros
        for (int i = 1; i < row; i++) {
            for (int j = 1; j < col; j++) {
                if (A[i][j] == 0) {
                    A[i][0] = 0;
                    A[0][j] = 0;
                }
            }
        }

        // Set zeros based on the marked first row and column
        for (int i = 1; i < row; i++) {
            for (int j = 1; j < col; j++) {
                if (A[i][0] == 0 || A[0][j] == 0) {
                    A[i][j] = 0;
                }
            }
        }

        // Set zeros in the first row and column if necessary
        if (firstRowHasZero) {
            for (int j = 0; j < col; j++) {
                A[0][j] = 0;
            }
        }

        if (firstColHasZero) {
            for (int i = 0; i < row; i++) {
                A[i][0] = 0;
            }
        }
    }
}
